  var aiHelp={
    taskType:{"普通评论生成":"用于日常口碑、产品体验、品牌讨论等常规内容的评论生成。","舆情应对生成":"用于争议、质疑或负面舆情中的回应、解释和讨论引导。"},
    mainType:{"高管个人言行类":"围绕企业高管的公开讲话、动态、体验、观点、站台等个人相关言行。","产品实力类":"围绕车辆硬件、性能、配置、技术、测试、做工质量等产品硬实力。","用户场景类":"围绕日常通勤、自驾、越野、露营、极地用车等真实使用场景。","服务运营类":"围绕售后、保养、救援、试驾、车友社群、用户活动与用户关怀。","购车转化类":"围绕导购咨询、价格、到店、新车上市、购车意向和选车决策。","竞品舆情类":"围绕竞品对比、争议反驳、回击回怼和竞对评价。","品牌价值类":"围绕品牌形象、文化、理念、担当、社会责任和品牌故事。","营销传播类":"围绕活动造势、跨界合作、明星助力、玩梗、营销战略与圈层传播。","用户口碑类":"围绕车主真实用车感受、用户反馈、车主故事、用户评价与用户共创。"},
    audience:{"技术专家":"以技术原理、研发和工程验证为主要观察视角。","行业专家":"以产业趋势、市场格局和行业经验进行专业判断。","评车人":"以车辆测评、横向体验和产品优缺点分析为视角。","汽车行业关注者":"长期关注汽车行业动态、技术与品牌变化的人群。","老车主":"已有较长用车经历，强调长期体验和历史对比。","新车主":"近期购车或提车，强调新鲜体验和初期反馈。","体验官":"以试驾、体验活动或产品深度体验者的身份表达。","车友":"以同品牌、同车型或共同用车兴趣圈层成员身份交流。","潜客":"已有兴趣但尚未购买，关注决策信息和真实体验。","消费者":"从一般消费选择、权益和产品价值角度表达。","家庭用户":"关注家庭乘坐、空间、安全、舒适和多人出行。","城市用户":"关注通勤、停车、能耗、补能和城市道路体验。","男性用户":"以男性用户常见兴趣和使用关注点组织表达。","女性用户":"以女性用户常见审美、便利、安全和体验关注点组织表达。","创业者":"关注效率、商务形象、成本和多场景生产力。","理性分析者":"强调事实、逻辑、数据与边界，不作情绪化判断。","路人网友":"无明确利益关联，以普通围观网友口吻自然参与讨论。","第三方视角":"不以车主或品牌拥护者自居，从外部观察者角度评价。","网络梗王":"善用网络流行语、轻松玩梗和有传播力的表达。","越野爱好者":"关注通过性、脱困、四驱、可靠性和越野场景。","改装爱好者":"关注改装空间、玩法、部件和个性化表达。","户外爱好者":"关注露营、装备装载、复杂环境和户外生活方式。","摩旅爱好者":"关注摩托旅行、长途骑行和沿途使用体验。","自驾游爱好者":"关注长途舒适、装载、路线适应和旅行体验。","长城品牌追随者":"长期关注并认同长城品牌、产品和技术路线。","中国品牌支持者":"关注中国汽车品牌进步、产业能力和文化自信。","科技受益者":"关注技术给日常生活带来的效率、便利和体验提升。","生活理念追随者":"关注产品所承载的生活方式、价值主张和情感认同。"},
    scene:{"高管相关":"内容落脚高管个人言行。","品牌文化":"仅讲企业或品牌整体，不落到个人。","产品硬实力":"硬件、参数、外观内饰和整车基础属性。","产品技术解读 & 测试":"技术解析、测评、极限场景和越野文化。","购车决策意向":"用户选车、咨询、新车上市和到店转化。","用户用车体验":"真实用车感受、车主声音和市场结果。","用户生态运营":"用户思维、社群、共创和互动。","市场与竞争舆情":"竞品对比、争议回击和海内外市场。","营销传播活动":"营销战略、合作、IP和热梗造势。","服务保障":"售后全链路、救援和保养。"},
    tone:{"中立讨论":"立场中立，无明显褒贬，以交流探讨为主。","理性克制":"即便持有正负观点，语言克制、不偏激。","期待种草":"作为接收端被内容打动，产生向往和期待。","轻度互动":"简单附和、表情或简短跟帖，无实质观点输出。","专业解释":"输出技术、配置类专业解读内容。","正向夸赞":"有理有据地对产品或品牌进行肯定夸奖。","疑问质询":"普通咨询、提问并寻求解答。","观望犹豫":"意向用户纠结观望，呈现持币待购心态。","调侃玩梗":"使用玩梗、戏谑或玩笑式表达。","安利推荐":"作为输出端主动向他人推荐产品。","客观求证":"专门核实信息真伪、求证事实。","感慨情怀":"抒发情怀、怀旧或价值感慨。"}
  };
