  function enhanceAssignModal(){var human=qs("#tailHumanFields"),ai=qs("#tailAiFields");if(human)human.insertAdjacentHTML("afterbegin",'<label class="tail-switch-row"><span><strong>评论免审核直接通过</strong><em>适用于已在线下审核完成的评论包；供应商提交后自动进入执行。</em></span><label class="tail-switch"><input id="tailHumanAutoApprove" type="checkbox"><span></span><b>默认关闭</b></label></label>');if(!ai)return;var selected=posts.filter(function(p){return state.selected.indexOf(p.id)>-1});ai.insertAdjacentHTML("afterbegin",'<section class="tail-content-summary"><div><strong>内容AI总结（含视频内容解析）</strong><span>AI同时输出新闻核心内容和评论撰写建议，作为后续生成依据。</span></div>'+selected.map(function(p){return'<article><b>'+esc(p.title)+'</b><div class="tail-summary-pair"><section><strong>新闻核心内容</strong><p>'+esc(p.excerpt)+'</p></section><section><strong>评论撰写建议</strong><p>'+esc(aiWritingAdvice(p))+'</p></section></div><em>已识别：'+esc(p.contentType)+' · '+esc(p.category)+' · '+esc(p.tone)+'</em></article>'}).join("")+'</section><div class="tail-requirement-mode"><strong>输出要求方式</strong><div><button type="button" class="'+(state.aiRequirementMode==="options"?'is-active':'')+'" data-ai-requirement-mode="options">选择输出要求</button><button type="button" class="'+(state.aiRequirementMode==="prompt"?'is-active':'')+'" data-ai-requirement-mode="prompt">手动输入要求</button></div><section id="tailAiPromptPanel" class="tail-ai-prompt-panel" '+(state.aiRequirementMode==="prompt"?'':'hidden')+'><div class="tail-ai-chat" id="tailAiPromptTurns"><article class="is-ai"><b>AI需求助手</b><p>请告诉我评论要表达什么、面向谁、采用什么语气。你可以继续补充或纠正，我会逐轮收敛为最终提示词。</p></article>'+state.aiPromptTurns.map(function(turn){return'<article class="is-'+turn.role+'"><b>'+(turn.role==="user"?'你':'AI需求助手')+'</b><p>'+esc(turn.text)+'</p></article>'}).join("")+'</div><div class="tail-ai-chat-compose"><textarea id="tailAiPromptInput" rows="3" placeholder="例如：先写得像真实车主，再补充：不要使用夸张词，每条观点要有差异……"></textarea><button type="button" class="tail-button is-primary" data-tail-action="send-ai-prompt-turn">发送给AI梳理</button></div><small>确认分派时，全部对话要求会合并为最终提示词；结构化选项在此模式下不参与生成。</small></section></div>');toggleAssignModeFields()}
  function aiWritingAdvice(p){var tag=(p.businessTags||[]).slice(-1)[0]||p.category||"核心事实";return"建议围绕“"+tag+"”提炼2—3个可讨论观点，结合"+p.model+"相关真实场景，保持"+(p.tone==="负面"?"克制回应、先解释后表达":"自然交流、避免广告腔")+"；不同评论使用差异化角度。"}
