  function customSelectValue(selector){var el=qs(selector);if(!el)return"";if(el.value!=="自定义")return el.value;var input=qs('[data-custom-for="'+el.id+'"]');return input&&input.value.trim()||"自定义"}
  function downloadRangeReport(){var start=qs("#tailReportStart").value,end=qs("#tailReportEnd").value,startMs=new Date(start).getTime(),endMs=new Date(end).getTime();if(!start||!end||startMs>=endMs){toast("请选择有效的开始和结束时间");return}var rows=brandFilteredTasks().filter(function(t){var stamp=taskTimestamp(t.created);return stamp>=startMs&&stamp<endMs}),completed=rows.filter(function(t){return t.status==="completed"}).length,canvas=document.createElement("canvas"),ctx=canvas.getContext("2d"),range=start.replace("T"," ")+" 至 "+end.replace("T"," ");canvas.width=1200;canvas.height=1580;ctx.fillStyle="#f3f6f9";ctx.fillRect(0,0,1200,1580);ctx.fillStyle="#fff";ctx.fillRect(70,60,1060,1460);ctx.fillStyle="#e88624";ctx.fillRect(70,60,12,180);ctx.fillStyle="#13263e";ctx.font="700 42px Microsoft YaHei";ctx.fillText("尾翼维护任务报告",120,130);ctx.fillStyle="#728197";ctx.font="22px Microsoft YaHei";ctx.fillText(range,120,180);ctx.fillStyle="#23394f";ctx.font="700 28px Microsoft YaHei";ctx.fillText("范围核心指标",120,300);[["下发任务",rows.length+" 条"],["完成任务",completed+" 条"],["完成率",percent(completed,rows.length)],["进行中",rows.length-completed+" 条"]].forEach(function(item,i){var x=120+(i%2)*480,y=350+Math.floor(i/2)*140;ctx.fillStyle=i===1?"#fff6e9":"#f5f8fb";ctx.fillRect(x,y,430,105);ctx.fillStyle="#748398";ctx.font="20px Microsoft YaHei";ctx.fillText(item[0],x+22,y+34);ctx.fillStyle="#14283f";ctx.font="700 34px Microsoft YaHei";ctx.fillText(item[1],x+22,y+78)});ctx.fillStyle="#23394f";ctx.font="700 28px Microsoft YaHei";ctx.fillText("供应商完成情况",120,700);suppliers.forEach(function(v,i){var y=750+i*100,all=rows.filter(function(t){return t.vendor===v}).length,done=rows.filter(function(t){return t.vendor===v&&t.status==="completed"}).length;ctx.fillStyle="#f7f9fc";ctx.fillRect(120,y,960,72);ctx.fillStyle="#32475f";ctx.font="700 21px Microsoft YaHei";ctx.fillText(v,145,y+30);ctx.font="19px Microsoft YaHei";ctx.fillText("下发 "+all+" 条",500,y+30);ctx.fillText("完成 "+done+" 条",700,y+30);ctx.fillText(percent(done,all),900,y+30)});ctx.fillStyle="#718197";ctx.font="18px Microsoft YaHei";ctx.fillText("统计范围：当前所选品牌 · "+range,120,1420);canvas.toBlob(function(blob){var a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="尾翼任务报告_"+start.slice(0,10)+"_"+end.slice(0,10)+".png";a.click();URL.revokeObjectURL(a.href)},"image/png");closeModal();toast("时间范围报告已生成")}

  function handleManualPostFile(file){if(!file)return;var ext=(file.name.split(".").pop()||"").toLowerCase();if(["xlsx","xls","csv"].indexOf(ext)<0){toast("请选择 .xlsx、.xls 或 .csv 文件");return}state.manualFileName=file.name;if(ext!=="csv"){state.manualBatchUrls=sampleBatchUrls();renderModal();toast("文件已上传并完成链接校验");return}var reader=new FileReader();reader.onload=function(){var rows=String(reader.result||"").split(/\r?\n/),urls=[];rows.forEach(function(row){var match=row.match(/https?:\/\/[^,，\s\"']+/i);if(match&&validWebUrl(match[0]))urls.push(match[0])});state.manualBatchUrls=unique(urls);renderModal();toast(state.manualBatchUrls.length?"已识别 "+state.manualBatchUrls.length+" 条有效链接":"未识别到有效 Web 链接")};reader.onerror=function(){state.manualBatchUrls=[];renderModal();toast("文件读取失败，请重新选择")};reader.readAsText(file,"utf-8")}
