  function confirmAddPosts(){var links=state.manualPostMode==="single"?state.manualUrls.map(function(url){return url.trim()}).filter(Boolean):state.manualBatchUrls.slice();if(state.manualPostMode==="single"&&!links.length){toast("请至少填写一条主贴链接");return}if(state.manualPostMode==="batch"&&!state.manualFileName){toast("请先上传填写完成的Excel文件");return}if(state.manualPostMode==="batch"&&!links.length){toast("文件中没有可导入的有效链接");return}var invalid=links.filter(function(url){return !validWebUrl(url)});if(invalid.length){toast("有 "+invalid.length+" 条链接格式不正确，请检查后再添加");return}links=unique(links.map(normalizeWebUrl));var existing=posts.map(function(p){return normalizeWebUrl(p.url||"")}),fresh=links.filter(function(url){return existing.indexOf(url)<0});if(!fresh.length){toast("这些链接已经在尾翼数据中心中");return}var brand=findBrand(state.manualPostBrand)||tailBrands[0],slot=currentTimeSlot();fresh.forEach(function(url,index){posts.unshift(createManualPost(url,brand,slot,index))});if(state.selectedBrands.indexOf(brand.id)<0)state.selectedBrands.push(brand.id);state.tab="history";state.keyword="";persist();closeModal();render();toast("已添加 "+fresh.length+" 条主贴，已切换到全部数据"+(fresh.length<links.length?"，重复链接已跳过":""))}
  function createManualPost(url,brand,slot,index){var host=webHost(url),platform=manualPlatform(host),stamp=manualTimestamp();return post({id:"post-manual-"+Date.now().toString(36)+"-"+index,slot:slot,title:"手动添加主贴 · "+host,excerpt:"已通过Web链接补充进入尾翼数据中心，标题、作者与传播数据将在解析完成后自动回填。",url:url,brand:brand.name,brandId:brand.id,model:"待识别",tone:"待识别",category:"手动补充",platform:platform,media:host,mediaLevel:"待识别",accountType:"待识别",author:host,followers:0,engagement:0,reposts:0,comments:0,growth:0,potential:0,sentiment:"待识别",contentType:"网页新闻",publish:stamp,tags:["手动添加","Web链接"]})}
  function validWebUrl(value){try{var parsed=new URL(value);return parsed.protocol==="http:"||parsed.protocol==="https:"}catch(e){return false}}
  function normalizeWebUrl(value){try{var parsed=new URL(value);parsed.hash="";return parsed.href.replace(/\/$/,"")}catch(e){return String(value||"").trim()}}
  function webHost(value){try{return new URL(value).hostname.replace(/^www\./,"")}catch(e){return"待识别来源"}}
  function manualPlatform(host){if(host.indexOf("weibo")>-1)return"微博";if(host.indexOf("weixin")>-1||host.indexOf("qq.com")>-1)return"微信";if(host.indexOf("xiaohongshu")>-1)return"小红书";if(host.indexOf("douyin")>-1)return"抖音";if(host.indexOf("autohome")>-1)return"汽车之家";if(host.indexOf("zhihu")>-1)return"知乎";return"网站"}
  function currentTimeSlot(){var hour=new Date().getHours(),found=timeTabs.filter(function(tab){return hour>=tab.start&&hour<tab.end})[0];return found?found.id:"slot-1"}
  function manualTimestamp(){var now=new Date(),pad=function(n){return String(n).padStart(2,"0")};return now.getFullYear()+"-"+pad(now.getMonth()+1)+"-"+pad(now.getDate())+" "+pad(now.getHours())+":"+pad(now.getMinutes())}
  function sampleBatchUrls(){var token=Date.now().toString(36);return["https://news.example.com/article/"+token+"-01","https://www.autohome.com.cn/news/"+token+"-02","https://media.example.com/story/"+token+"-03"]}

  function findBrand(id){return tailBrands.filter(function(brand){return brand.id===id})[0]||null}
  function saveBrandDefinition(){var editing=findBrand(state.modal.id),name=(qs("#tailBrandName").value||"").trim(),desc=(qs("#tailBrandDesc").value||"").trim();if(!name){toast("请填写品牌名称");return}if(tailBrands.some(function(brand){return brand.name===name&&(!editing||brand.id!==editing.id)})){toast("品牌名称已存在");return}if(editing){var oldName=editing.name;editing.name=name;editing.desc=desc||name+"相关传播数据";posts.forEach(function(p){if(p.brandId===editing.id)p.brand=name});persist();render();openModal("brand-manager");toast(oldName===name?"品牌说明已更新":"品牌名称已同步更新");return}var id="brand-"+Date.now().toString(36);tailBrands.push({id:id,name:name,desc:desc||name+"相关传播数据"});state.brandConfigs[id]=createBrandConfigs()[id];state.selectedBrands.push(id);state.activeBrand=id;persist();render();openModal("brand-manager");toast("品牌已创建，请继续配置数据源和初筛规则")}
  function deleteBrandDefinition(id){if(tailBrands.length<=1){toast("至少保留一个品牌");return}var brand=findBrand(id);if(!brand){toast("未找到品牌");return}tailBrands=tailBrands.filter(function(item){return item.id!==id});delete state.brandConfigs[id];state.selectedBrands=state.selectedBrands.filter(function(item){return item!==id});if(state.activeBrand===id)state.activeBrand=tailBrands[0].id;persist();render();openModal("brand-manager");toast(brand.name+"已从品牌配置中删除")}
  function confirmAssign(){var vendor=qs("#tailAssignVendor").value,mode=qs("#tailAssignMode").value,countInput=qs("#tailCommentCount").value.trim(),count=mode==="ai"?Number(countInput):Number((countInput.match(/\d+/)||[])[0]||10),countRequirement=mode==="ai"?countInput+"条":countInput,humanReq=qs("#tailHumanRequirement")?qs("#tailHumanRequirement").value.trim():"",humanType=(qs('[name="tailHumanCommentType"]:checked')||{}).value||"日常评论",autoApprove=!!(qs("#tailHumanAutoApprove")&&qs("#tailHumanAutoApprove").checked);if(mode==="ai"&&(!count||count<1||count>100||Math.floor(count)!==count)){toast("AI撰写的评论数量请输入1至100之间的整数");return}if(mode==="human"&&!countInput){toast("请填写人工撰写的评论数量要求");return}count=Math.max(1,Math.min(100,count||10));if(mode==="human"&&!humanReq){toast("请填写人工撰写统一要求");return}if(mode==="ai"&&state.aiRequirementMode==="prompt"&&!state.aiPromptTurns.some(function(turn){return turn.role==="user"})&&!(qs("#tailAiPromptInput")&&qs("#tailAiPromptInput").value.trim())){toast("请至少输入一轮AI提示词要求");return}if(mode==="ai"&&qsa("[data-ai-comment-length]").some(function(input){return Number(input.value)<10||Number(input.value)>300})){toast("单条评论目标字数请输入10至300之间的整数");return}state.selected.forEach(function(id){var p=findPost(id),settings=mode==="ai"?collectAiSettings(id,p):null,req=mode==="ai"?(settings.prompt||aiSettingsSummary(settings)):humanReq;p.assign=vendor;var cs=[];if(mode==="ai")for(var i=0;i<count;i++)cs.push(comment(generateAiComment(p,i,settings),"pending"));tasks.unshift(task({id:"task-"+Date.now()+"-"+id.slice(-3),postId:id,vendor:vendor,mode:mode,commentType:mode==="human"?humanType:"AI评论",status:mode==="ai"?"internal_review":"vendor_pending",requirement:req,commentCount:count,commentCountRequirement:countRequirement,aiSettings:settings,autoApprove:autoApprove,comments:cs}))});state.selected=[];persist();closeModal();render();toast(mode==="ai"?"AI已生成"+count+"条评论并进入内部审核":humanType+"任务已发送供应商，等待接收")}
  function saveTabFilter(){var id=state.modal.id,platforms=checkedValues("filterPlatforms"),mediaLevels=checkedValues("filterMediaLevels"),originals=checkedValues("filterOriginals"),sentiments=checkedValues("filterSentiments"),fans=Math.max(0,Number(qs("#tailFans").value||0)),engagement=Math.max(0,Number(qs("#tailEngagement").value||0));if(!platforms.length){toast("媒体平台请至少选择一项");return}if(!mediaLevels.length){toast("媒体等级请至少选择一项");return}if(!originals.length){toast("原创 / 转载请至少选择一项");return}if(!sentiments.length){toast("内容情感请至少选择一项");return}tabFilters[id]={platforms:platforms,mediaLevels:mediaLevels,fans:fans,engagement:engagement,originals:originals,sentiments:sentiments,includeKeyword:qs("#tailIncludeKeyword").value.trim(),excludeKeyword:qs("#tailExcludeKeyword").value.trim()};persist();closeModal();render();toast("当前时间段筛选条件已保存并生效")}
  function checkedValues(name){return qsa('input[name="'+name+'"]:checked').map(function(input){return input.value})}
  function createTimeTab(){toast("14:00-15:00与“午间窗口”重叠，请先调整原时间段边界")}
  function deleteTimeTab(id){var index=timeTabs.findIndex(function(tab){return tab.id===id});if(index<0){closeModal();return}var removed=timeTabs[index];timeTabs.splice(index,1);delete tabFilters[id];if(state.tab===id)state.tab="history";persist();closeModal();render();toast("已删除“"+removed.name+"”，关联主贴仍可在全部数据中查看")}
  function deletePosts(ids){ids.forEach(function(id){var p=findPost(id);p.deleted=true;p.deletedAt="2026-08-14 10:00"});state.selected=[];persist();render();toast("信息已移入今日垃圾筐")}
  function submitVendorComments(t){var editors=qsa("[data-vendor-comment]"),missing=false,producedAt=manualTimestamp();editors.forEach(function(editor){var index=Number(editor.getAttribute("data-vendor-comment")),existing=t.comments[index];if(existing&&existing.status==="approved")return;var value=editor.value.trim();if(!value){missing=true;return}if(existing){existing.text=value;existing.status=t.autoApprove?"approved":"pending";existing.rewriteRequirement="";existing.producedAt=producedAt}else{t.comments[index]=comment(value,t.autoApprove?"approved":"pending");t.comments[index].producedAt=producedAt}});if(missing||t.comments.length<t.commentCount){toast("请完整填写需要撰写或重写的评论内容");return}t.status=t.autoApprove?"export_ready":"vendor_submitted";t.feedback="";var round=currentRound(t);if(round)round.status=t.autoApprove?"待执行":"待审核";persist();render();toast(t.autoApprove?"评论已自动通过，可直接执行":"需重写的评论已提交，已通过评论保持不变")}
  function reconcileReviewState(t){if(t.mode!=="human")return;var pending=t.comments.some(function(c){return c.status==="pending"}),rejected=t.comments.filter(function(c){return c.status==="rejected"}),round=currentRound(t);if(pending){t.status="vendor_submitted";if(round)round.status="审核中";return}if(rejected.length){t.status="returned";t.feedback=unique(rejected.map(function(c){return c.rewriteRequirement}).filter(Boolean)).join("；")||"请重写未通过评论";if(round)round.status="退回重写"}else{t.status="export_ready";if(round)round.status="待发布"}}
  function rewriteAiComment(){var t=findTask(state.modal.id),c=findComment(t,state.modal.extra),req=qs("#tailRewriteRequirement").value.trim();if(!req){toast("请填写本次重写要求");return}c.rewriteRequirement=req;c.text="结合主贴讨论来看，真正值得关注的是实际场景中的体验变化。"+req.replace(/[。！!]+$/,'')+"，这样的观点会更有参考价值。";c.status="pending";persist();closeModal();render();toast("AI已按新要求重新生成")}

  function visiblePosts(){return posts.filter(function(p){if(p.deleted||p.assign||!brandSelected(p))return false;if(!matchesTab(p)||!matchesSavedFilter(p)||!matchesBusinessTag(p))return false;if(state.keyword&&[p.title,p.media].concat(p.tags,p.businessTags||[]).join(" ").toLowerCase().indexOf(state.keyword.toLowerCase())<0)return false;return true}).sort(function(a,b){return b.publish.localeCompare(a.publish)})}
  function matchesBusinessTag(p){var values=p.businessTags||[];if(state.businessL1!=="all"&&values[0]!==state.businessL1)return false;if(state.businessL2!=="all"&&values[1]!==state.businessL2)return false;if(state.businessL3!=="all"&&values[2]!==state.businessL3)return false;return true}
  function matchesTab(p){return state.tab==="history"||p.slot===state.tab}
  function matchesSavedFilter(p){if(state.tab==="history"||!tabFilters[state.tab])return true;var f=tabFilters[state.tab],text=[p.title,p.excerpt,p.media].concat(p.tags).join(" "),mediaLevel=p.mediaLevel.indexOf("普通")>-1?"一般":"重点",originality=p.contentType.indexOf("原创")>-1?"原创":"转载";if(f.platforms.length&&!f.platforms.some(function(key){return filterPlatformMatchesPost(key,p)}))return false;if(p.followers<Number(f.fans||0))return false;if(p.engagement<Number(f.engagement||0))return false;if(f.mediaLevels.indexOf(mediaLevel)<0)return false;if(f.originals.indexOf(originality)<0)return false;if(f.sentiments.indexOf(p.sentiment)<0)return false;if(f.includeKeyword&&!keywordMatch(text,f.includeKeyword,true))return false;if(f.excludeKeyword&&keywordMatch(text,f.excludeKeyword,false))return false;return true}
  function filterPlatformMatchesPost(key,p){var parts=String(key).split("|"),group=parts[0],item=parts[1]||parts[0],platform=p.platform||"";if(platform===item||platform.indexOf(item)>-1||item.indexOf(platform)>-1)return true;if(group==="weibo")return platform.indexOf("微博")>-1;if(group==="wechat")return platform.indexOf("微信")>-1;if(group==="video")return platform===item;if(group==="app")return platform===item;if(group==="website")return platform.indexOf("新闻")>-1||["汽车之家","易车网","懂车帝","太平洋汽车","爱卡汽车","网上车市","汽车头条"].indexOf(platform)>-1;if(group==="forum")return platform.indexOf("论坛")>-1||platform.indexOf("贴吧")>-1||["汽车之家","易车网"].indexOf(platform)>-1;if(group==="qa")return platform.indexOf("问答")>-1||["知乎","百度知道","搜狗问问","360问答","中关村在线"].indexOf(platform)>-1;if(group==="newspaper")return platform.indexOf("报")>-1;return false}
  function savedFilterSummary(f){return"平台 "+(f.platforms.length||currentFilterPlatforms().length)+"项 · 媒体等级 "+f.mediaLevels.join("/")+" · 粉丝≥"+format(f.fans)+" · 互动≥"+format(f.engagement)+" · "+f.originals.join("/")+" · "+f.sentiments.join("/")}
  function filterNumber(v){if(!v||v==="不限")return 0;var n=parseFloat(String(v).replace(/[^\d.]/g,""))||0;return String(v).indexOf("万")>-1?n*10000:n}
  function keywordMatch(text,value,all){var words=String(value).split(/[，,、\s]+/).filter(Boolean);if(!words.length)return false;return all?words.every(function(w){return text.indexOf(w)>-1}):words.some(function(w){return text.indexOf(w)>-1})}
  function matchMedia(p,v){if(v==="central")return p.mediaLevel.indexOf("中央")>-1;if(v==="industry")return p.mediaLevel.indexOf("行业")>-1||p.mediaLevel.indexOf("KOL")>-1;if(v==="community")return p.accountType==="自然用户"||p.mediaLevel.indexOf("社区")>-1;return true}
  function visibleTasks(){return brandFilteredTasks().filter(function(t){var created=taskTimestamp(t.created),start=state.taskStart?new Date(state.taskStart).getTime():null,end=state.taskEnd?new Date(state.taskEnd).getTime():null;if(start!==null&&created<start)return false;if(end!==null&&created>=end)return false;if(state.vendor!=="all"&&t.vendor!==state.vendor)return false;if(state.taskStatus!=="all"&&!taskGroupMatch(t,state.taskStatus))return false;return true})}
  function taskTimestamp(value){return new Date(String(value||"").replace(" ","T")).getTime()}
  function visibleVendorTasks(){return tasks.filter(function(t){if(t.vendor!=="星河传播")return false;if(state.taskScope==="today"&&!todayTask(t))return false;if(state.vendorStatus!=="all"&&!vendorGroupMatch(t,state.vendorStatus))return false;var p=findPost(t.postId);if(!p||!brandSelected(p))return false;return!state.keyword||[t.id,p.title,p.brand,p.model,p.platform,p.author].join(" ").toLowerCase().indexOf(state.keyword.toLowerCase())>-1})}
  function taskGroupMatch(t,g){var m={writing:["vendor_pending","vendor_writing","returned"],review:["vendor_submitted","internal_review"],executing:["export_ready","vendor_executing"],validation:["evidence_review"],rejected:["vendor_rejected"],completed:["completed"]};return(m[g]||[]).indexOf(t.status)>-1}
  function vendorGroupMatch(t,g){var m={receiving:["vendor_pending"],writing:["vendor_writing","returned"],waiting:["vendor_submitted","internal_review"],executable:["export_ready"],executing:["vendor_executing","evidence_review"],rejected:["vendor_rejected"],completed:["completed"]};return(m[g]||[]).indexOf(t.status)>-1}

  function stepper(t){var order=page==="vendor-detail"?["接收任务","评论撰写","等待审核","执行维护","验收完成"]:["分派任务","评论撰写","内部审核","供应商执行","验收完成"],idx=stageIndex(t.status);return'<section class="tail-stepper">'+order.map(function(s,i){return'<div class="tail-step '+(i<idx?'is-done':i===idx?'is-active':'')+'"><b>'+(i<idx?'✓':i+1)+'</b><span>'+s+'</span></div>'}).join("")+'</section>'}
  function stageIndex(s){if(s==="vendor_pending"||s==="vendor_rejected")return 0;if(s==="vendor_writing"||s==="returned")return 1;if(s==="vendor_submitted"||s==="internal_review")return 2;if(s==="export_ready"||s==="vendor_executing")return 3;if(s==="evidence_review"||s==="completed")return 4;return 0}
  function sourceBlock(p){return'<div class="tail-block-head"><h2>主贴原文</h2><button class="tail-button" data-tail-action="open-original" data-post-id="'+p.id+'">打开原文</button></div><h2 class="tail-source-title">'+esc(p.title)+'</h2><div class="tail-source-meta"><span>'+esc(p.platform)+' · '+esc(p.media)+'</span><span>'+esc(p.publish)+'</span><span>粉丝 '+format(p.followers)+'</span><span>互动 '+format(p.engagement)+'</span></div><div class="tail-source-content">'+esc(p.excerpt)+'</div>'}
  function taskSummary(t,p){var settings=t.aiSettings||null,ai=settings?aiSettingsPanel(settings,p):"";return'<div class="tail-block-head"><h2>任务信息</h2>'+taskValidationStatus(t)+'</div><div class="tail-task-meta-grid"><span><b>任务编号</b>'+esc(t.id.toUpperCase())+'</span><span><b>评论方式</b>'+(t.mode==="ai"?'AI撰写':'供应商人工撰写')+'</span><span><b>评论类型</b>'+esc(commentTypeLabel(t))+'</span><span><b>评论数量要求</b>'+esc(t.commentCountRequirement||t.commentCount+'条')+'</span><span><b>'+(page==="vendor-detail"?'接收时间':'下发时间')+'</b>'+t.created+'</span></div><div class="tail-task-requirement"><strong>'+(t.mode==="ai"?'评论生成要求':'人工撰写统一要求')+'</strong><p>'+esc(t.requirement)+'</p></div>'+ai}
  function aiSettingsPanel(settings,p){return'<div class="tail-ai-settings-summary"><strong>AI生成设置</strong><span>任务类型：'+esc(settings.taskType||"-")+'</span><span>品牌 / 车型：'+esc((settings.models||[]).join("、")||p.model)+'</span><span>话术类型：'+esc((settings.mainTypes||[]).join("、")||settings.mainType||"-")+'</span><span>适配人群：'+esc((settings.audiences||[]).join("、")||"-")+'</span><span>上评场景：'+esc((settings.scenes||[]).join("、")||settings.scene||"-")+'</span><span>语气倾向：'+esc((settings.tones||[]).join("、")||settings.tone||"-")+'</span><span>目标字数：'+esc(settings.commentLength||40)+' 字 / 条</span><span class="is-wide">AI提示词：'+esc(settings.itemPrompt||settings.prompt||"-")+'</span></div>'}
